Lemma gsi_1RB0LD_1RC1RA_0LC1LD_0RA1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LD_1RC1RA_0LC1LD_0RA1LD.
