    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1RC1RA_0LC1LD_0RA1LD B0_1RB0LD_1RC1RA_0LC1LD_0RA1LD B1_1RB0LD_1RC1RA_0LC1LD_0RA1LD 4 12 p j' [] []).
    + exact run_ovf_1RB0LD_1RC1RA_0LC1LD_0RA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1RC1RA_0LC1LD_0RA1LD p j' E).
    + exact (geo_1RB0LD_1RC1RA_0LC1LD_0RA1LD p j' E).
    + lia.
