(** ** The lap *)

Lemma lap_1RB0LD_1RC1RA_0LD1LD_0RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
