  - destruct (lapi_1RB0LD_1RC1RA_0LD1LD_0RA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1RC1RA_0LD1LD_0RA1LC B0_1RB0LD_1RC1RA_0LD1LD_0RA1LC B1_1RB0LD_1RC1RA_0LD1LD_0RA1LC 4 12 p j' [] []).
    + exact run_ovf_1RB0LD_1RC1RA_0LD1LD_0RA1LC.
    + reflexivity.
    + reflexivity.
