Definition BM0_1RB0LD_1RC1RA_1LA0LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition BM1_1RB0LD_1RC1RA_1LA0LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition chm_1RB0LD_1RC1RA_1LA0LD_0RB1LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_shift_1RB0LD_1RC1RA_1LA0LD_0RB1LD : srun tm true true chm_1RB0LD_1RC1RA_1LA0LD_0RB1LD BM0_1RB0LD_1RC1RA_1LA0LD_0RB1LD = Some (BM1_1RB0LD_1RC1RA_1LA0LD_0RB1LD, 4, 4).
