(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LD_1RC1RA_1LA0LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S0;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB0LD_1RC1RA_1LA0LD_0RB1LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB0LD_1RC1RA_1LA0LD_0RB1LD : srun tm true true che_1RB0LD_1RC1RA_1LA0LD_0RB1LD BE0_1RB0LD_1RC1RA_1LA0LD_0RB1LD = Some (B1_1RB0LD_1RC1RA_1LA0LD_0RB1LD, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LD_1RC1RA_1LA0LD_0RB1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LD_1RC1RA_1LA0LD_0RB1LD.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0LD_1RC1RA_1LA0LD_0RB1LD, cden, A0_1RB0LD_1RC1RA_1LA0LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

