  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 8), (cden [] [] j BB1_1RB0LD_1RC1RA_1LA0LD_0RB1LD).
    split; [lia|]. split; [| exact (gbo_1RB0LD_1RC1RA_1LA0LD_0RB1LD j)].
    rewrite (gso_1RB0LD_1RC1RA_1LA0LD_0RB1LD p j E).
