    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S1] j ++ [S1;S0;S0;S1], S0, []))).
  { unfold Cin_1RB0LD_1RC1RA_1LA1RB_0RB1LD. rewrite epow2_1RB0LD_1RC1RA_1LA1RB_0RB1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
