(** ** The lap *)

Lemma lap_1RB0LD_1RC1RA_1LA1RB_0RB1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
