Lemma fireo_1RB0LD_1RC1RA_1LA1RB_0RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1RC1RA_1LA1RB_0RB1LD = Some t ->
