Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LD_1RC1RA_1LA1RB_0RB1LD t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB0LD_1RC1RA_1LA1RB_0RB1LD). split;
      [| exact (gbo_1RB0LD_1RC1RA_1LA1RB_0RB1LD j)].
