               run_boot_1RB0LD_1RC1RA_1LC0LD_0RB1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
