(** 1RB0LD_1RC1RA_1LC1LB_0RA1LD *)
(** 1RB0LD_1RC1RA_1LC1LB_0RA1LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LD_1RC1RA_1LC1LB_0RA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StC | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DL StD end.

(** Its mirror 1LB0RD_1LC1LA_1RC1RB_0LA1RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LD_1RC1RA_1LC1LB_0RA1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S1 DR StC | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LD_1RC1RA_1LC1LB_0RA1LD : list Instr := [].
Definition tmw_1RB0LD_1RC1RA_1LC1LB_0RA1LD : TM := tm_wrap_trs tmm_1RB0LD_1RC1RA_1LC1LB_0RA1LD pins_1RB0LD_1RC1RA_1LC1LB_0RA1LD.
Local Notation tm := tmw_1RB0LD_1RC1RA_1LC1LB_0RA1LD.

Lemma mirror_ok_1RB0LD_1RC1RA_1LC1LB_0RA1LD : mirror_tm tm_1RB0LD_1RC1RA_1LC1LB_0RA1LD = tmm_1RB0LD_1RC1RA_1LC1LB_0RA1LD.
