    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LD_1RC1RA_1LC1LB_0RB1LD p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (4 * j + 4), (cden [] [] j BM1_1RB0LD_1RC1RA_1LC1LB_0RB1LD).
