(** The chain into this family lands on its anchor up to 2/1
    trailing blanks. *)
Lemma gbo_1RB0LD_1RC1RA_1LC1LD_0RA1LD : forall j, lift (cden [] [] j BB1_1RB0LD_1RC1RA_1LC1LD_0RA1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LD_1RC1RA_1LC1LD_0RA1LD = (StA, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LD_1RC1RA_1LC1LD_0RA1LD, sden;
