Lemma lapi_1RB0LD_1RC1RA_1LC1RD_0RB1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB0LD_1RC1RA_1LC1RD_0RB1LD p j q0 E).
