  unfold Cin_1RB0LD_1RC1RA_1LC1RD_0RB1LD, cden, BE0_1RB0LD_1RC1RA_1LC1RD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
