(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB0LD_1RC1RA_1LC1RD_0RB1LD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB0LD_1RC1RA_1LC1RD_0RB1LD = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB0LD_1RC1RA_1LC1RD_0RB1LD q p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB0LD_1RC1RA_1LC1RD_0RB1LD). split;
      [| exact (gbo_1RB0LD_1RC1RA_1LC1RD_0RB1LD j)].
    rewrite (gso_1RB0LD_1RC1RA_1LC1RD_0RB1LD p j E).
