    exact (srun_sound tm true true chb_1RB0LD_1RC1RA_1LC1RD_0RB1LD B0_1RB0LD_1RC1RA_1LC1RD_0RB1LD BB1_1RB0LD_1RC1RA_1LC1RD_0RB1LD 4 4
             run_boot_1RB0LD_1RC1RA_1LC1RD_0RB1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LD_1RC1RA_1LC1RD_0RB1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LD_1RC1RA_1LC1RD_0RB1LD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1RC1RA_1LC1RD_0RB1LD : forall t, ~ In t pins_1RB0LD_1RC1RA_1LC1RD_0RB1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_1RC1RA_1LC1RD_0RB1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC1RA_1LC1RD_0RB1LD (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RA_1LC1RD_0RB1LD [SRotL 1; SWin 1; SCycL 2 0; SWinL 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LD_1RC1RA_1LC1RD_0RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC1RA_1LC1RD_0RB1LD (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RA_1LC1RD_0RB1LD [SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LD_1RC1RA_1LC1RD_0RB1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC1RA_1LC1RD_0RB1LD (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RA_1LC1RD_0RB1LD [SRotL 1; SWin 1; SCycL 2 0; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC1RA_1LC1RD_0RB1LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RA_1LC1RD_0RB1LD [SRotL 1; SWin 1; SCycL 2 0; SWinL 4] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LD_1RC1RA_1LC1RD_0RB1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_1RC1RA_1LC1RD_0RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LD_1RC1RA_1LC1RD_0RB1LD : NeverQuasiHaltsTr tmm_1RB0LD_1RC1RA_1LC1RD_0RB1LD.
Proof.
  apply (glue_neverqhtr tmm_1RB0LD_1RC1RA_1LC1RD_0RB1LD pins_1RB0LD_1RC1RA_1LC1RD_0RB1LD Cc 4).
  - exact boot_1RB0LD_1RC1RA_1LC1RD_0RB1LD.
