Lemma lapi_1RB0LD_1RC1RA_1LD1RA_0RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
