  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_1RC1RA_1LD1RB_0RC1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1RC1RA_1LD1RB_0RC1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
