(** The chain into this family lands on its anchor up to 2/1
    trailing blanks. *)
Lemma gbo_1RB0LD_1RC1RA_1LD____0RA1LD : forall j, lift (cden [] [] j BB1_1RB0LD_1RC1RA_1LD____0RA1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LD_1RC1RA_1LD____0RA1LD = (StA, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB0LD_1RC1RA_1LD____0RA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_1RB0LD_1RC1RA_1LD____0RA1LD. rewrite epow2_1RB0LD_1RC1RA_1LD____0RA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LD_1RC1RA_1LD____0RA1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LD_1RC1RA_1LD____0RA1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LD_1RC1RA_1LD____0RA1LD.
Proof.
