(** ** Bootstrap *)

Lemma boot_1RB0LD_1RC1RA_1LD____0RA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
