Lemma gen_1RB0LD_1RC1RA_1LD____0RB1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ []) [] i AI1_1RB0LD_1RC1RA_1LD____0RB1LD) = lift (Cin (Pos.succ v)).
