  split; [lia|]. split; [| exact (gen_1RB0LD_1RC1RA_1LD____0RB1LD v i q0 E)].
  rewrite (gsn_1RB0LD_1RC1RA_1LD____0RB1LD v i q0 E).
  exact (srun_sound tm false true chn_1RB0LD_1RC1RA_1LD____0RB1LD AI0_1RB0LD_1RC1RA_1LD____0RB1LD AI1_1RB0LD_1RC1RA_1LD____0RB1LD 4 4
           run_inner_1RB0LD_1RC1RA_1LD____0RB1LD (Jp q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
