Lemma gen_1RB0LD_1RC1RB_0LA0RB_1RB1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1;S1]) [] i AI1_1RB0LD_1RC1RB_0LA0RB_1RB1LA) = lift (Cin (Pos.succ v)).
Proof.
