  split; [lia|]. split; [| exact (gen_1RB0LD_1RC1RB_0LA0RB_1RB1LA v i q0 E)].
  rewrite (gsn_1RB0LD_1RC1RB_0LA0RB_1RB1LA v i q0 E).
  exact (srun_sound tm false true chn_1RB0LD_1RC1RB_0LA0RB_1RB1LA AI0_1RB0LD_1RC1RB_0LA0RB_1RB1LA AI1_1RB0LD_1RC1RB_0LA0RB_1RB1LA 4 4
           run_inner_1RB0LD_1RC1RB_0LA0RB_1RB1LA (Ip q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
