  assert (HD : cden [] [] j BB1_1RB0LD_1RC1RB_0LA0RB_1RB1LA = (StC, (rep [S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold cden, BB1_1RB0LD_1RC1RB_0LA0RB_1RB1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
