    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin_1RB0LD_1RC1RB_0LA0RB_1RB1LA. rewrite epow2_1RB0LD_1RC1RB_0LA0RB_1RB1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
