Definition mk_1RB0LD_1RC1RB_0LA1LB_1LA0RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LD_1RC1RB_0LA1LB_1LA0RB.

(** 1RB0LD_1RC1RB_0LA1LB_1LA0RB *)
Definition tm_1RB0LD_1RC1RB_0LA1LB_1LA0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S0 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LD_1RC1RB_0LA1LB_1LA0RB : list Instr := [].
Definition tmw_1RB0LD_1RC1RB_0LA1LB_1LA0RB : TM := tm_wrap_trs tm_1RB0LD_1RC1RB_0LA1LB_1LA0RB pins_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
Local Notation tm := tmw_1RB0LD_1RC1RB_0LA1LB_1LA0RB.

Definition Cc_1RB0LD_1RC1RB_0LA1LB_1LA0RB (p : positive) : cconf := (StC, (Jp p ++ [S1;S1;S0], S0, [])).
Local Notation Cc := Cc_1RB0LD_1RC1RB_0LA1LB_1LA0RB.

(** ** The certificate *)

Definition A0_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB0LD_1RC1RB_0LA1LB_1LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 4; SWin 1; SUnrotL 1].

Lemma run_int_1RB0LD_1RC1RB_0LA1LB_1LA0RB : srun tm false true chi_1RB0LD_1RC1RB_0LA1LB_1LA0RB A0_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Some (A1_1RB0LD_1RC1RB_0LA1LB_1LA0RB, 6, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StC *)
Definition Cin_1RB0LD_1RC1RB_0LA1LB_1LA0RB (v : positive) : cconf := (StC, (Jp v ++ [S0;S1], S0, [])).
Local Notation Cin := Cin_1RB0LD_1RC1RB_0LA1LB_1LA0RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB0LD_1RC1RB_0LA1LB_1LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 4; SWin 1; SUnrotL 1].

Lemma run_inner_1RB0LD_1RC1RB_0LA1LB_1LA0RB : srun tm false true chn_1RB0LD_1RC1RB_0LA1LB_1LA0RB AI0_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Some (AI1_1RB0LD_1RC1RB_0LA1LB_1LA0RB, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB0LD_1RC1RB_0LA1LB_1LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 4; SWin 1; SUnrotL 1].

Lemma run_boot_1RB0LD_1RC1RB_0LA1LB_1LA0RB : srun tm true true chb_1RB0LD_1RC1RB_0LA1LB_1LA0RB B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Some (BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB0LD_1RC1RB_0LA1LB_1LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 8; SCycR 4; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB0LD_1RC1RB_0LA1LB_1LA0RB : srun tm true true che_1RB0LD_1RC1RB_0LA1LB_1LA0RB BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Some (B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB, 6, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S1;S0]) [] j A0_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0LD_1RC1RB_0LA1LB_1LA0RB, cden, A0_1RB0LD_1RC1RB_0LA1LB_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S1;S1;S0]) [] j A1_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB0LD_1RC1RB_0LA1LB_1LA0RB, cden, A1_1RB0LD_1RC1RB_0LA1LB_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (6 * j + 4). split; [lia|].
  rewrite (gsi_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LD_1RC1RB_0LA1LB_1LA0RB A0_1RB0LD_1RC1RB_0LA1LB_1LA0RB A1_1RB0LD_1RC1RB_0LA1LB_1LA0RB 6 4
             run_int_1RB0LD_1RC1RB_0LA1LB_1LA0RB (Jp q0 ++ [S1;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j q0 E).
Qed.

Lemma gso_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB0LD_1RC1RB_0LA1LB_1LA0RB, cden, B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB
             = (StC, (rep [S1;S1] (S j) ++ [S1;S1;S1], S0, []))).
  { unfold cden, B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1] (S j) ++ [S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LD_1RC1RB_0LA1LB_1LA0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LD_1RC1RB_0LA1LB_1LA0RB. reflexivity.
Qed.

Lemma gsn_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ [S0;S1]) [] i AI0_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_1RB0LD_1RC1RB_0LA1LB_1LA0RB, cden, AI0_1RB0LD_1RC1RB_0LA1LB_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ [S0;S1]) [] i AI1_1RB0LD_1RC1RB_0LA1LB_1LA0RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (_ & H2).
  unfold Cin_1RB0LD_1RC1RB_0LA1LB_1LA0RB, cden, AI1_1RB0LD_1RC1RB_0LA1LB_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 4), (cden (Jp q0 ++ [S0;S1]) [] i AI1_1RB0LD_1RC1RB_0LA1LB_1LA0RB).
  split; [lia|]. split; [| exact (gen_1RB0LD_1RC1RB_0LA1LB_1LA0RB v i q0 E)].
  rewrite (gsn_1RB0LD_1RC1RB_0LA1LB_1LA0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB0LD_1RC1RB_0LA1LB_1LA0RB AI0_1RB0LD_1RC1RB_0LA1LB_1LA0RB AI1_1RB0LD_1RC1RB_0LA1LB_1LA0RB 6 4
           run_inner_1RB0LD_1RC1RB_0LA1LB_1LA0RB (Jp q0 ++ [S0;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall j, lift (cden [] [] j BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB = (StC, ((rep [S1;S1] j ++ [S1;S0;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S1] j ++ [S1;S0;S1], S0, []))).
  { unfold Cin_1RB0LD_1RC1RB_0LA1LB_1LA0RB. rewrite epow2_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LD_1RC1RB_0LA1LB_1LA0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LD_1RC1RB_0LA1LB_1LA0RB, cden, BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LD_1RC1RB_0LA1LB_1LA0RB p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB).
    split; [lia|]. split; [| exact (gbo_1RB0LD_1RC1RB_0LA1LB_1LA0RB j)].
    rewrite (gso_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j E).
    exact (srun_sound tm true true chb_1RB0LD_1RC1RB_0LA1LB_1LA0RB B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB 6 4
             run_boot_1RB0LD_1RC1RB_0LA1LB_1LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 12), (cden [] [] j B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB).
    split; [| exact (geo_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j E)].
    rewrite (gxi_1RB0LD_1RC1RB_0LA1LB_1LA0RB j).
    exact (srun_sound tm true true che_1RB0LD_1RC1RB_0LA1LB_1LA0RB BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB B1_1RB0LD_1RC1RB_0LA1LB_1LA0RB 6 12
             run_exit_1RB0LD_1RC1RB_0LA1LB_1LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LD_1RC1RB_0LA1LB_1LA0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 12.
  assert (H : match csteps tm 12 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LD_1RC1RB_0LA1LB_1LA0RB t p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB). split;
      [| exact (gbo_1RB0LD_1RC1RB_0LA1LB_1LA0RB j)].
    rewrite (gso_1RB0LD_1RC1RB_0LA1LB_1LA0RB p j E).
    exact (srun_sound tm true true chb_1RB0LD_1RC1RB_0LA1LB_1LA0RB B0_1RB0LD_1RC1RB_0LA1LB_1LA0RB BB1_1RB0LD_1RC1RB_0LA1LB_1LA0RB 6 4
             run_boot_1RB0LD_1RC1RB_0LA1LB_1LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LD_1RC1RB_0LA1LB_1LA0RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LD_1RC1RB_0LA1LB_1LA0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1RC1RB_0LA1LB_1LA0RB : forall t, ~ In t pins_1RB0LD_1RC1RB_0LA1LB_1LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
