      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0LD_1RC1RB_0LA1LB_1LA0RB : NeverQuasiHaltsTr tm_1RB0LD_1RC1RB_0LA1LB_1LA0RB.
