  unfold Cc_1RB0LD_1RC1RB_1LC1LA_0RA0LD, cden, P0_1RB0LD_1RC1RB_1LC1LA_0RA0LD, P1_1RB0LD_1RC1RB_1LC1LA_0RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
