  - destruct (gz_1RB0LD_1RC1RB_1LC1LA_0RA0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 6), (cden (Dp q0 ++ [S0]) [] 0 Z1_1RB0LD_1RC1RB_1LC1LA_0RA0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB0LD_1RC1RB_1LC1LA_0RA0LD Z0_1RB0LD_1RC1RB_1LC1LA_0RA0LD Z1_1RB0LD_1RC1RB_1LC1LA_0RA0LD 0 6
             run_z_1RB0LD_1RC1RB_1LC1LA_0RA0LD (Dp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB0LD_1RC1RB_1LC1LA_0RA0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 10), (cden (Dp q0 ++ [S0]) [] j' P1_1RB0LD_1RC1RB_1LC1LA_0RA0LD).
    split; [lia|]. split; [| exact HB].
