    exact (srun_sound tm false true chp_1RB0LD_1RC1RB_1LC1LA_0RA0LD P0_1RB0LD_1RC1RB_1LC1LA_0RA0LD P1_1RB0LD_1RC1RB_1LC1LA_0RA0LD 4 10
             run_p_1RB0LD_1RC1RB_1LC1LA_0RA0LD (Dp q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LD_1RC1RB_1LC1LA_0RA0LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LD_1RC1RB_1LC1LA_0RA0LD.
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (H1 & _).
  unfold Cc_1RB0LD_1RC1RB_1LC1LA_0RA0LD, cden, B0_1RB0LD_1RC1RB_1LC1LA_0RA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
