(** ** Bootstrap *)

Lemma boot_1RB0LD_1RC1RB_1LD1RC_0RB1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 27.
  assert (H : match csteps tm 27 c0 with
