Lemma fireo_1RB0LD_1RC1RB_1LD1RC_0RB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1RC1RB_1LD1RC_0RB1LA = Some t ->
