  apply (fire_via_fill tm Cc Cin lapin_1RB0LD_1RC1RB_1LD1RC_0RB1LA t p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB0LD_1RC1RB_1LD1RC_0RB1LA). split;
      [| exact (gbo_1RB0LD_1RC1RB_1LD1RC_0RB1LA j)].
