Lemma fire_1RB0LD_1RC1RC_1LD1RA_0RC1LD : forall t, ~ In t pins_1RB0LD_1RC1RC_1LD1RA_0RC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
