    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RC_1LD1RA_0RC1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC1RC_1LD1RA_0RC1LD (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RC_1LD1RA_0RC1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LD_1RC1RC_1LD1RA_0RC1LD (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LD_1RC1RC_1LD1RA_0RC1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
