    apply (lap_of_run tm Cc true true cho_1RB0RA_0LC0LD_1RA1LB_1RC1LD B0_1RB0RA_0LC0LD_1RA1LB_1RC1LD B1_1RB0RA_0LC0LD_1RA1LB_1RC1LD 4 20 p j' [] []).
    + exact run_ovf_1RB0RA_0LC0LD_1RA1LB_1RC1LD.
