Lemma lapi_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
