Lemma geo_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RA_0LC0RA_1RA0LD_1RA1LC) = lift (Cc (Pos.succ p)).
