  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB0RA_0LC0RA_1RA0LD_1RA1LC p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (4 * j + 6), (cden [] [] j BB1_1RB0RA_0LC0RA_1RA0LD_1RA1LC).
      split; [lia|]. split; [| exact (gbo_1RB0RA_0LC0RA_1RA0LD_1RA1LC j)].
      rewrite (gso_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j E).
      exact (srun_sound tm true true chb_1RB0RA_0LC0RA_1RA0LD_1RA1LC B0_1RB0RA_0LC0RA_1RA0LD_1RA1LC BB1_1RB0RA_0LC0RA_1RA0LD_1RA1LC 4 6
               run_boot_1RB0RA_0LC0RA_1RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0RA_0LC0RA_1RA0LD_1RA1LC p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (4 * j + 4), (cden [] [] j BM1_1RB0RA_0LC0RA_1RA0LD_1RA1LC).
      split; [| exact (gbo2_1RB0RA_0LC0RA_1RA0LD_1RA1LC j)].
      rewrite (gxi_1RB0RA_0LC0RA_1RA0LD_1RA1LC j).
      exact (srun_sound tm true true chm_1RB0RA_0LC0RA_1RA0LD_1RA1LC BM0_1RB0RA_0LC0RA_1RA0LD_1RA1LC BM1_1RB0RA_0LC0RA_1RA0LD_1RA1LC 4 4
               run_shift_1RB0RA_0LC0RA_1RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (4 * j + 8), (cden [] [] j B1_1RB0RA_0LC0RA_1RA0LD_1RA1LC).
    split; [| exact (geo_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j E)].
    rewrite (gxi2_1RB0RA_0LC0RA_1RA0LD_1RA1LC j).
    exact (srun_sound tm true true che_1RB0RA_0LC0RA_1RA0LD_1RA1LC BE0_1RB0RA_0LC0RA_1RA0LD_1RA1LC B1_1RB0RA_0LC0RA_1RA0LD_1RA1LC 4 8
             run_exit_1RB0RA_0LC0RA_1RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RA_0LC0RA_1RA0LD_1RA1LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RA_0LC0RA_1RA0LD_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0RA_0LC0RA_1RA0LD_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 6), (cden [] [] j BB1_1RB0RA_0LC0RA_1RA0LD_1RA1LC).
    split; [lia|]. split; [| exact (gbo_1RB0RA_0LC0RA_1RA0LD_1RA1LC j)].
    rewrite (gso_1RB0RA_0LC0RA_1RA0LD_1RA1LC p j E).
    exact (srun_sound tm true true chb_1RB0RA_0LC0RA_1RA0LD_1RA1LC B0_1RB0RA_0LC0RA_1RA0LD_1RA1LC BB1_1RB0RA_0LC0RA_1RA0LD_1RA1LC 4 6
             run_boot_1RB0RA_0LC0RA_1RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0RA_0LC0RA_1RA0LD_1RA1LC p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 4), (cden [] [] j BM1_1RB0RA_0LC0RA_1RA0LD_1RA1LC).
    split; [| exact (gbo2_1RB0RA_0LC0RA_1RA0LD_1RA1LC j)].
    rewrite (gxi_1RB0RA_0LC0RA_1RA0LD_1RA1LC j).
    exact (srun_sound tm true true chm_1RB0RA_0LC0RA_1RA0LD_1RA1LC BM0_1RB0RA_0LC0RA_1RA0LD_1RA1LC BM1_1RB0RA_0LC0RA_1RA0LD_1RA1LC 4 4
             run_shift_1RB0RA_0LC0RA_1RA0LD_1RA1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB0RA_0LC0RA_1RA0LD_1RA1LC t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB0RA_0LC0RA_1RA0LD_1RA1LC xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB0RA_0LC0RA_1RA0LD_1RA1LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RA_0LC0RA_1RA0LD_1RA1LC : forall t, ~ In t pins_1RB0RA_0LC0RA_1RA0LD_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RA_0LC0RA_1RA0LD_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RA_0LC0RA_1RA0LD_1RA1LC (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RA_0LC0RA_1RA0LD_1RA1LC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RA_0LC0RA_1RA0LD_1RA1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0RA_0LC0RA_1RA0LD_1RA1LC : NeverQuasiHaltsTr tm_1RB0RA_0LC0RA_1RA0LD_1RA1LC.
Proof.
  apply (glue_neverqhtr tm_1RB0RA_0LC0RA_1RA0LD_1RA1LC pins_1RB0RA_0LC0RA_1RA0LD_1RA1LC Cc 1).
  - exact boot_1RB0RA_0LC0RA_1RA0LD_1RA1LC.
  - intros p _. apply lap_1RB0RA_0LC0RA_1RA0LD_1RA1LC.
  - intros t Ht p _. apply fire_1RB0RA_0LC0RA_1RA0LD_1RA1LC. exact Ht.
Qed.

Theorem nonhalt_1RB0RA_0LC0RA_1RA0LD_1RA1LC : NonHalt tm_1RB0RA_0LC0RA_1RA0LD_1RA1LC.
