Lemma fireo_1RB0RA_0LC0RB_1RA0LD_1LC0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RA_0LC0RB_1RA0LD_1LC0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
