    apply (lap_of_run tm Cc true true cho_1RB0RA_0LC1RA_0RB0LD_1LC1LD B0_1RB0RA_0LC1RA_0RB0LD_1LC1LD B1_1RB0RA_0LC1RA_0RB0LD_1LC1LD 8 22 p j' [] []).
