(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RA_0LC1RA_1LA0LD_1LB1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_0000_1111_1111 q0 ++ [S0]) [] 0 Z0_1RB0RA_0LC1RA_1LA0LD_1LB1LD /\
  lift (cden (Ap_Alph_0000_1111_1111 q0 ++ [S0]) [] 0 Z1_1RB0RA_0LC1RA_1LA0LD_1LB1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_0000_1111_1111.cview_some_Alph_0000_1111_1111 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0RA_0LC1RA_1LA0LD_1LB1LD, cden, Z0_1RB0RA_0LC1RA_1LA0LD_1LB1LD, Z1_1RB0RA_0LC1RA_1LA0LD_1LB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

