(** 1RB0RA_0RC0LA_1LD0RC_0LD1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RA_0RC0LA_1LD0RC_0LD1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S1 DL StA end.

